  if (num1 === '0' || num2 === '0') return '0';
  const n1 = num1.split('').reverse().map(Number);
  const n2 = num2.split('').reverse().map(Number);
  const product = Array(n1.length + n2.length).fill(0);

  for (let i = 0; i < n1.length; i++) {
