  let carry = 0;
  for (let i = 0; i < productArray.length; i++) {
    const sum = productArray[i] + carry;
    productArray[i] = sum % 10;
    carry = Math.floor(sum / 10);
  }

  while (productArray.length > 1 && productArray[productArray.length - 1] === 0) {
