const isValidParentheses = (s) => {
  const stack = [];

  const isOpenBracket = (char) => ['(', '{', '['].includes(char);
  const isCloseBracket = (char) => [')', '}', ']'].includes(char);
  const getMatchingOpenBracket = (char) => {
    if (char === ')') return '(';
    if (char === '}') return '{';
    if (char === ']') return '[';
    return null;
  };
  const areBracketsMatching = (open, close) => getMatchingOpenBracket(close) === open;
  const pushToStack = (val) => stack.push(val);
  const popFromStack = () => stack.pop();
  const isStackEmpty = () => stack.length === 0;

  for (const char of s) {
    if (isOpenBracket(char)) {
      pushToStack(char);
    } else if (isCloseBracket(char)) {
      if (isStackEmpty() || !areBracketsMatching(popFromStack(), char)) {
        return false;
      }
    }
  }

  return isStackEmpty();
};

