const sumPrimesUpTo = (n) => {
  const isNumberPrime = (num) => {
    if (num <= 1) return false;
    for (let i = 2; i * i <= num; i++) {
      if (num % i === 0) return false;
    }
    return true;
  };

  const initializeSum = () => 0;
  const incrementSum = (currentSum, value) => currentSum + value;
  const createNumberRange = (limit) => Array.from({ length: limit + 1 }, (_, i) => i);
  const filterPrimeNumbers = (numbers) => numbers.filter(isNumberPrime);
  const sumNumbersInArray = (numbers) => numbers.reduce(incrementSum, initializeSum());

  const allNumbers = createNumberRange(n);
  const primeNumbers = filterPrimeNumbers(allNumbers);
  const finalSum = sumNumbersInArray(primeNumbers);

  return finalSum;
};

