const removeHyphens = (isbn) => isbn.replace(/-/g, '');
const isCorrectLength = (isbn) => isbn.length === 10;
const convertCharToDigit = (char) => (char === 'X' ? 10 : parseInt(char, 10));
const calculateWeightedSum = (digits) =>
  digits.reduce((sum, digit, index) => sum + digit * (10 - index), 0);
const isDivisibleByEleven = (sum) => sum % 11 === 0;
const containsOnlyValidChars = (isbn) => /^[0-9X]+$/.test(isbn);

const isValidISBN10 = (isbn) => {
  const cleanedIsbn = removeHyphens(isbn);
  if (!isCorrectLength(cleanedIsbn)) {
    return false;
  }
  if (!containsOnlyValidChars(cleanedIsbn)) {
    return false;
  }
  const digits = cleanedIsbn.split('').map(convertCharToDigit);
  const totalSum = calculateWeightedSum(digits);
  return isDivisibleByEleven(totalSum);
};

