const simulateQueue = (initialQueue, operations) => {
  let currentQueueState = [...initialQueue];

  const createNewQueue = (arr) => [...arr];
  const isEnqueueOperation = (op) => op.type === 'enqueue';
  const extractEnqueueValue = (op) => op.value;
  const addElementToEnd = (queue, element) => {
    const newQueue = createNewQueue(queue);
    newQueue.push(element);
    return newQueue;
  };
  const removeFirstElement = (queue) => {
    const newQueue = createNewQueue(queue);
    newQueue.shift();
    return newQueue;
  };
  const isDequeueOperation = (op) => op.type === 'dequeue';

  for (const operation of operations) {
    if (isEnqueueOperation(operation)) {
      const valueToAdd = extractEnqueueValue(operation);
      currentQueueState = addElementToEnd(currentQueueState, valueToAdd);
    } else if (isDequeueOperation(operation)) {
      currentQueueState = removeFirstElement(currentQueueState);
    }
  }

  return currentQueueState;
};

