  const newStartsDuringExisting = isBetween(newStart, existingStart, existingEnd - 1);
  const newEndsDuringExisting = isBetween(newEnd - 1, existingStart, existingEnd - 1);
  const existingStartsDuringNew = isBetween(existingStart, newStart, newEnd - 1);

  return newStartsDuringExisting || newEndsDuringExisting || existingStartsDuringNew;
};

