  const ConvertPercentageToDecimal = (percentage) => percentage / 100;
  const MultiplyBillByDecimal = (bill, decimal) => bill * decimal;
  const RoundTipToTwoDecimals = (tip) => Math.round(tip * 100) / 100;

  const tipDecimal = ConvertPercentageToDecimal(tipPercentage);
  const rawTipAmount = MultiplyBillByDecimal(billTotal, tipDecimal);
  const finalTipAmount = RoundTipToTwoDecimals(rawTipAmount);

  const FormatOutput = (amount) => parseFloat(amount.toFixed(2));
  const ValidateInput = (bill, percentage) => typeof bill === 'number' && typeof percentage === 'number' && bill >= 0 && percentage >= 0;
  const ThrowInvalidInputError = () => { throw new Error("Invalid input: billTotal and tipPercentage must be non-negative numbers."); };

  if (!ValidateInput(billTotal, tipPercentage)) {
    ThrowInvalidInputError();
  }

  return FormatOutput(finalTipAmount);
};

