const getMinLength = (strings) => Math.min(...strings.map(str => str.length));

const getLastChar = (str, indexFromEnd) => str[str.length - 1 - indexFromEnd];

const areAllCharsSameAtIndex = (strings, indexFromEnd) => {
  const char = getLastChar(strings[0], indexFromEnd);
  return strings.every(str => getLastChar(str, indexFromEnd) === char);
};

const buildSuffixString = (charsArray) => charsArray.reverse().join('');

const isArrayEmpty = (arr) => arr.length === 0;

const getFirstString = (strings) => strings[0];

const longestCommonSuffix = (strings) => {
  if (isArrayEmpty(strings)) {
    return '';
  }
  if (strings.length === 1) {
    return getFirstString(strings);
  }

  const minLen = getMinLength(strings);
  const commonChars = [];

  for (let i = 0; i < minLen; i++) {
    if (areAllCharsSameAtIndex(strings, i)) {
      commonChars.push(getLastChar(getFirstString(strings), i));
    } else {
      break;
    }
  }

  return buildSuffixString(commonChars);
};

