const calculateAbsoluteDifference = (a, b) => Math.abs(a - b);
const calculateXDifference = (x1, x2) => calculateAbsoluteDifference(x1, x2);
const calculateYDifference = (y1, y2) => calculateAbsoluteDifference(y1, y2);
const sumAbsoluteDifferences = (diffX, diffY) => diffX + diffY;

const manhattanDistance = (x1, y1, x2, y2) => {
  const getXDifference = (val1, val2) => calculateXDifference(val1, val2);
  const getYDifference = (val1, val2) => calculateYDifference(val1, val2);

  const xDiff = getXDifference(x1, x2);
  const yDiff = getYDifference(y1, y2);

  const finalSum = sumAbsoluteDifferences(xDiff, yDiff);
  return finalSum;
};

