  const [hours, minutes] = timeString.split(':').map(Number);
  return hours * 60 + minutes;
};

const getEventStartTime = event => parseTimeString(event.start);
const getEventEndTime = event => parseTimeString(event.end);

const isTimeBefore = (time1, time2) => time1 < time2;
const isTimeAfter = (time1, time2) => time1 > time2;

const checkOverlap = (event1, event2) => {
  const event1Start = getEventStartTime(event1);
  const event1End = getEventEndTime(event1);
  const event2Start = getEventStartTime(event2);
  const event2End = getEventEndTime(event2);

  return !isTimeAfter(event1Start, event2End) && !isTimeBefore(event1End, event2Start);
};

const getOverlappingEvents = (newEvent, existingEvents) => {
  const overlapping = [];
  for (const existingEvent of existingEvents) {
    if (checkOverlap(newEvent, existingEvent)) {
      overlapping.push(existingEvent);
    }
  }
  return overlapping;
};

