const isValidEmail = (email) => {
  const containsAtSymbol = (str) => str.includes('@');
  const containsDotSymbol = (str) => str.includes('.');
  const doesNotStartWithAt = (str) => !str.startsWith('@');
  const doesNotEndWithAt = (str) => !str.endsWith('@');
  const doesNotStartWithDot = (str) => !str.startsWith('.');
  const doesNotEndWithDot = (str) => !str.endsWith('.');

  if (!containsAtSymbol(email)) return false;
  if (!containsDotSymbol(email)) return false;

  const [localPart, domainPart] = email.split('@');

  if (localPart.length === 0 || domainPart.length === 0) return false;

  if (!doesNotStartWithAt(email) || !doesNotEndWithAt(email)) return false;
  if (!doesNotStartWithDot(email) || !doesNotEndWithDot(email)) return false;

  return true;
};

