const isValidLuhn = (cardNumber) => {
  const sanitizeInput = (numStr) => numStr.replace(/\s/g, '');
  const convertToDigits = (sanitizedNum) => sanitizedNum.split('').map(Number);
  const doubleEvenIndexedDigits = (digits) =>
    digits.map((digit, index) => (index % 2 === 0 ? digit * 2 : digit));
  const subtractNineIfGreaterThanNine = (doubledDigits) =>
    doubledDigits.map((digit) => (digit > 9 ? digit - 9 : digit));
  const sumAllDigits = (processedDigits) =>
    processedDigits.reduce((acc, current) => acc + current, 0);
  const isSumDivisibleByTen = (totalSum) => totalSum % 10 === 0;

  const sanitizedCardNumber = sanitizeInput(cardNumber);
  if (sanitizedCardNumber.length === 0) return false;

  const digits = convertToDigits(sanitizedCardNumber).reverse();
  const doubledDigits = doubleEvenIndexedDigits(digits);
  const processedDigits = subtractNineIfGreaterThanNine(doubledDigits);
  const totalSum = sumAllDigits(processedDigits);

  return isSumDivisibleByTen(totalSum);
};

