const getBinaryLength = (binaryString) => binaryString.length;
const getCharAtIndex = (binaryString, index) => binaryString[index];
const isCharOne = (char) => char === '1';
const calculatePowerOfTwo = (exponent) => Math.pow(2, exponent);
const addValueToSum = (currentSum, valueToAdd) => currentSum + valueToAdd;
const initializeDecimalSum = () => 0;

const binToDec = (binaryString) => {
  let decimalSum = initializeDecimalSum();
  const len = getBinaryLength(binaryString);
  for (let i = 0; i < len; i++) {
    const char = getCharAtIndex(binaryString, i);
    if (isCharOne(char)) {
      const power = len - 1 - i;
      const value = calculatePowerOfTwo(power);
      decimalSum = addValueToSum(decimalSum, value);
    }
  }
  return decimalSum;
};

