const initializeMatrix = (rows, cols) => Array.from({ length: rows }, () => Array(cols).fill(0));
const getMinValue = (a, b, c) => Math.min(a, b, c);
const getCharacterAtIndex = (str, index) => str[index];
const incrementValue = (value) => value + 1;
const areCharactersEqual = (char1, char2) => char1 === char2;
const getSubstitutionCost = (char1, char2) => areCharactersEqual(char1, char2) ? 0 : 1;

const levenshteinDistance = (s1, s2) => {
  const m = incrementValue(s1.length);
  const n = incrementValue(s2.length);
  const dp = initializeMatrix(m, n);

  for (let i = 0; i < m; i++) dp[i][0] = i;
  for (let j = 0; j < n; j++) dp[0][j] = j;

  for (let i = 1; i < m; i++) {
    for (let j = 1; j < n; j++) {
      const char1 = getCharacterAtIndex(s1, i - 1);
      const char2 = getCharacterAtIndex(s2, j - 1);
      const cost = getSubstitutionCost(char1, char2);

      const deletion = incrementValue(dp[i - 1][j]);
      const insertion = incrementValue(dp[i][j - 1]);
      const substitution = dp[i - 1][j - 1] + cost;

      dp[i][j] = getMinValue(deletion, insertion, substitution);
    }
  }
  return dp[s1.length][s2.length];
};

