const convertComponentToHex = (c) => c.toString(16);
const padHexComponent = (hex) => hex.padStart(2, '0');
const ensureValidComponent = (c) => Math.max(0, Math.min(255, c));
const formatHexCode = (hex) => `#${hex}`;
const processColorComponent = (component) => padHexComponent(convertComponentToHex(ensureValidComponent(component)));
const concatenateHexComponents = (rHex, gHex, bHex) => rHex + gHex + bHex;

const rgbToHex = (r, g, b) => {
  const hexR = processColorComponent(r);
  const hexG = processColorComponent(g);
  const hexB = processColorComponent(b);
  const fullHex = concatenateHexComponents(hexR, hexG, hexB);
  return formatHexCode(fullHex);
};

